import React, { useEffect, useRef } from 'react';
import HexagonPulseBackground from '../components/HexagonPulseBackground';
import PlasmaLavaLampBackground from '../components/PlasmaLavaLampBackground';
import { Link } from 'react-router-dom';
import implant1 from '../assets/highlight1.png';
import implant2 from '../assets/highlight2.png';
import implant3 from '../assets/highlight3.png';
import implant4 from '../assets/highlight4.png';
import implant5 from '../assets/highlight5.png';

export default function DentalToothImplant() {
  const heroBgRef = useRef(null);
  const plasmaRef = useRef(null);
  const revealObserverRef = useRef(null);

  useEffect(() => {
    // Parallax scroll for hero background and plasma layer
    const onScroll = () => {
      const y = window.scrollY || window.pageYOffset;
      if (heroBgRef.current) {
        // subtle slower upward movement
        heroBgRef.current.style.transform = `translateY(${y * 0.12}px)`;
      }
      if (plasmaRef.current) {
        // slower opposite movement for depth
        plasmaRef.current.style.transform = `translateY(${y * -0.03}px)`;
      }
    };
    window.addEventListener('scroll', onScroll, { passive: true });

    // Reveal-on-scroll for elements with .reveal
    const reveals = document.querySelectorAll('.reveal');
    const io = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
        }
      });
    }, { threshold: 0.15 });
    reveals.forEach((el) => io.observe(el));
    revealObserverRef.current = io;

    // initial run
    onScroll();

    return () => {
      window.removeEventListener('scroll', onScroll);
      if (revealObserverRef.current) revealObserverRef.current.disconnect();
    };
  }, []);

  return (
    <div className="relative min-h-screen bg-white overflow-x-hidden">
      {/* Full-page hexagon pulse background (behind all content) */}
      <div className="absolute inset-0 -z-40 pointer-events-none" aria-hidden>
        <HexagonPulseBackground />
      </div>
      {/* Hero Section with Hexagon Pulse Background */}
      <section className="relative flex flex-col items-center justify-center h-[220px] md:h-[340px] w-full mb-4 md:mb-8 overflow-hidden">
        {/* Modern layered gradients and glow */}
        <div className="absolute inset-0 z-0 pointer-events-none" ref={heroBgRef} style={{ transform: 'translateY(0px)', transition: 'transform 0.1s linear' }}>
          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[90vw] h-[60%] bg-gradient-to-br from-cyan-400 via-cyan-200 to-pink-300 opacity-40 blur-2xl rounded-full animate-pulse"></div>
          <div className="absolute bottom-0 right-1/3 w-[50vw] h-[30%] bg-gradient-to-tr from-pink-400 via-cyan-300 to-cyan-100 opacity-30 blur-3xl rounded-full animate-pulse"></div>
        </div>
        <div className="absolute inset-0 -z-10" aria-hidden>
          <HexagonPulseBackground />
        </div>
        <div className="relative z-10 text-center flex flex-col items-center">
          <h1 className="text-2xl md:text-4xl font-extrabold text-cyan-700 drop-shadow-2xl mb-2 md:mb-4 tracking-tight animate-fade-in">Dental Tooth Implant</h1>
          <p className="text-xs md:text-base text-gray-600 max-w-2xl mx-auto mb-2 md:mb-3">The animated mesh and plasma layers visually represent our advanced planning and precision during implant placement — combining cutting-edge imaging, stable biocompatible materials, and a patient-first treatment plan.</p>
          <Link to="/book-online" aria-label="Book Dental Implant consultation" className="mt-2 md:mt-4">
            <button className="px-5 md:px-8 py-2 md:py-3 rounded-full bg-gradient-to-r from-cyan-600 to-pink-500 text-white font-semibold text-base md:text-lg shadow-xl hover:scale-105 hover:from-cyan-700 hover:to-pink-600 transition-all duration-300 animate-fade-in">Book Online</button>
          </Link>
        </div>
        <style>{`
          @keyframes fade-in {
            0% { opacity: 0; transform: translateY(30px); }
            100% { opacity: 1; transform: translateY(0); }
          }
          .animate-fade-in {
            animation: fade-in 1.2s cubic-bezier(.4,0,.2,1) both;
          }
        `}</style>
      </section>

      {/* Modern Image Grid */}
      <section className="max-w-5xl mx-auto px-2 md:px-4 mb-6 md:mb-10">
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3 md:gap-6">
          <img src={implant1} alt="Dental Implant 1" className="reveal rounded-2xl shadow-lg object-cover w-full h-36 md:h-64 transform opacity-0 translate-y-6 hover:scale-105 transition-transform duration-700" />
          <img src={implant2} alt="Dental Implant 2" className="reveal rounded-2xl shadow-lg object-cover w-full h-36 md:h-64 transform opacity-0 translate-y-6 hover:scale-105 transition-transform duration-700" />
          <img src={implant3} alt="Dental Implant 3" className="reveal rounded-2xl shadow-lg object-cover w-full h-36 md:h-64 transform opacity-0 translate-y-6 hover:scale-105 transition-transform duration-700" />
          <img src={implant4} alt="Dental Implant 4" className="reveal rounded-2xl shadow-lg object-cover w-full h-36 md:h-64 transform opacity-0 translate-y-6 hover:scale-105 transition-transform duration-700" />
          <img src={implant5} alt="Dental Implant 5" className="reveal rounded-2xl shadow-lg object-cover w-full h-36 md:h-64 transform opacity-0 translate-y-6 hover:scale-105 transition-transform duration-700" />
        </div>
      </section>

      {/* Description Section - full width, mobile responsive */}
      <section className="w-full px-2 md:px-8 pb-8 md:pb-16">
        <h2 className="text-lg md:text-2xl font-bold text-cyan-800 mb-2 md:mb-4 text-center">What is a Dental Tooth Implant?</h2>
        <p className="reveal text-base md:text-lg text-gray-700 leading-relaxed max-w-screen-xl mx-auto">
          Dental implants are a revolutionary solution for replacing missing teeth, offering unparalleled stability, aesthetics, and functionality. Unlike traditional dentures or bridges, dental implants are surgically placed into the jawbone, where they fuse with the bone through a process called osseointegration. This creates a strong foundation for artificial teeth, such as crowns, bridges, or dentures, that look and feel just like natural teeth. Implants are typically made of biocompatible titanium, ensuring long-term durability and minimal risk of rejection. The procedure involves careful planning, precise placement, and a period of healing, after which the final restoration is attached. Dental implants not only restore your smile but also preserve facial structure, prevent bone loss, and improve overall oral health. They allow you to eat, speak, and smile with confidence, without worrying about slippage or discomfort. At Urja Dental Clinic, our experienced team uses advanced technology and personalized care to ensure optimal results for every patient. Whether you need a single tooth replacement or a full-mouth restoration, dental implants can transform your quality of life. Schedule a consultation today to discover how dental implants can help you regain your natural smile and enjoy lasting comfort and confidence.
        </p>
      </section>

      {/* Animated plasma/lava lamp background in front */}
      <div ref={plasmaRef} style={{ transform: 'translateY(0px)', transition: 'transform 0.15s linear' }}>
        <PlasmaLavaLampBackground />
      </div>
      <style>{`
        /* reveal-on-scroll */
        .reveal { will-change: transform, opacity; }
        .reveal.is-visible, .is-visible { opacity: 1 !important; transform: translateY(0px) !important; }
        .is-visible { transition: opacity 700ms ease-out, transform 700ms cubic-bezier(.22,.9,.36,1); }
        .reveal { opacity: 0; transform: translateY(24px); }
      `}</style>
    </div>
  );
}
